// PASS paint
in vec2 vs_uv;
out vec4 fs_color;

uniform float u_time;
uniform float u_aspect;
uniform vec2 u_resolution;

void main() {
    // center & aspect-correct
    vec2 p = vs_uv * 2.0 - 1.0;
    p.x *= u_aspect;

    // warm disc on the left
    float d1 = SB_sd_circle(p - vec2(-0.5, 0.0), 0.3);
    float m1 = SB_fill_aa(d1);
    vec3 col1 = vec3(1.0, 0.6, 0.2);

    // cool disc on the right
    float d2 = SB_sd_circle(p - vec2(0.5, 0.0), 0.3);
    float m2 = SB_fill_aa(d2);
    vec3 col2 = vec3(0.2, 0.6, 1.0);

    // thin dark wall down the middle
    float wb = SB_sd_box(p, vec2(0.02, 1.0));
    float mw = SB_fill_aa(wb);
    vec3 cw = vec3(0.05);

    vec3 col = m1 * col1 + m2 * col2 + mw * cw;
    fs_color = vec4(col, 1.0);
