args.old_str:
#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

void main() {
    fs_color = vec4(0.0, 0.0, 0.0, 1.0);
}

args.new_str:
#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform float u_aspect;

void main() {
    vec2 centered = vs_uv * 2.0 - 1.0;
    centered.x *= u_aspect;

    vec2 warmCenter = vec2(-0.35, 0.0);
    vec2 coolCenter = vec2(0.35, 0.08);

    float radius = 0.35;
    float edge = 0.014;

    float warmDist = length(centered - warmCenter);
    float coolDist = length(centered - coolCenter);

    float warmMask = 1.0 - smoothstep(radius - edge, radius, warmDist);
    float coolMask = 1.0 - smoothstep(radius - edge, radius, coolDist);

    vec3 warmColor = vec3(1.0, 0.55, 0.15) * 1.1;
    vec3 coolColor = vec3(0.2, 0.6, 1.0) * 1.1;

    vec3 discColor = warmColor * warmMask + coolColor * coolMask;

    float wallWidth = 0.018;
    float wallMask = 1.0 - smoothstep(0.0, wallWidth, abs(centered.x));
    vec3 wallColor = vec3(0.02);

    vec3 finalColor = mix(discColor, wallColor, wallMask);
    finalColor *= smoothstep(1.0, 0.0, length(centered)) * 1.0 + 0.0; // keep within view

    fs_color = vec4(finalColor, 1.0);
}

