args.new_text:
#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform float u_aspect;

void main() {
    vec2 centered = vs_uv * 2.0 - 1.0;
    centered.x *= u_aspect;

    const vec2 warmCenter = vec2(-0.33, -0.05);
    const vec2 coolCenter = vec2(0.35, 0.08);
    const float radius = 0.33;
    const float edge = 0.012;
    const float wallWidth = 0.01;

    float warmDist = length(centered - warmCenter);
    float coolDist = length(centered - coolCenter);

    float warmMask = 1.0 - smoothstep(radius - edge, radius + edge, warmDist);
    float coolMask = 1.0 - smoothstep(radius - edge, radius + edge, coolDist);
    float wallSoft = smoothstep(wallWidth, wallWidth + 0.003, abs(centered.x));
    float wallMask = 1.0 - wallSoft;

    vec3 warmColor = vec3(1.0, 0.55, 0.2) * 1.04;
    vec3 coolColor = vec3(0.15, 0.65, 1.0) * 1.1;
    vec3 wallColor = vec3(0.02);

    vec3 discColor = warmColor * warmMask + coolColor * coolMask;
    vec3 resultColor = mix(discColor, wallColor, wallMask);

    float vignette = 1.0 - smoothstep(1.0, 1.2, length(centered));
    resultColor *= vignette;

    fs_color = vec4(resultColor, 1.0);
}

args.old_str:
#version 460 core

in vec2 vs_uv; // Coordinate of the current pixel to be shaded

uniform float u_time;   // Time (s) since the application started
uniform float u_aspect; // Aspect ratio of the canvas (width / height)
// uniform vec2 u_resolution;  // Resolution of the canvas (width, height)

out vec4 fs_color;

void main() {
    float blue = abs(fract(0.5 * u_time) - 0.5);
    vec3 color = vec3(vs_uv, blue);
    fs_color = vec4(color, 1.0);
}

args.new_str:
#version 460 core

in vec2 vs_uv;

uniform sampler2D u_paint;

out vec4 fs_color;

void main() {
    vec4 paintSample = texture(u_paint, vs_uv);
    float brightness = max(max(paintSample.r, paintSample.g), paintSample.b);
    float solid = step(0.01, brightness);

    fs_color = vec4(vs_uv, 0.0, solid);
}

