 9  uniform int u_pass_iteration;
10  
11  const float HUGE_DIST = 1e6;
12  
13  vec4 readInput(vec2 uv) {
14      if (u_pass_iteration == 0) {
15          return texture(u_seed, uv);
16      }
17      return texture(u_prev, uv);
18  }
19  
20  void main() {
21      vec2 clampedUV = clamp(vs_uv, vec2(0.0), vec2(1.0));
22      vec4 best = readInput(clampedUV);
23  
24      float maxRes = max(u_resolution.x, u_resolution.y);
25      maxRes = max(maxRes, 1.0);
26      float log2Max = ceil(log2(maxRes));
27      float offsetPower = log2Max - 1.0 - float(u_pass_iteration);
28      offsetPower = max(offsetPower, 0.0);
29      float pixelOffset = exp2(offsetPower);
30      vec2 texelOffset = vec2(pixelOffset / u_resolution.x, pixelOffset / u_resolution.y);
31  
32      float bestDist2 = HUGE_DIST;
33      if (best.a > 0.0) {
34          vec2 delta = best.xy - clampedUV;
35          bestDist2 = dot(delta, delta);
36      }
37  
38      for (int y = -1; y <= 1; ++y) {
39          for (int x = -1; x <= 1; ++x) {
40              vec2 sampleOffset = vec2(float(x), float(y)) * texelOffset;
41              vec2 sampleUV = clamp(clampedUV + sampleOffset, vec2(0.0), vec2(1.0));
42              vec4 candidate = readInput(sampleUV);
43              if (candidate.a <= 0.0) {
44                  continue;
45              }
46  
47              vec2 delta = candidate.xy - clampedUV;
48              float dist2 = dot(delta, delta);
49              if (dist2 < bestDist2) {
50                  bestDist2 = dist2;
51                  best = candidate;
52              }
53          }
54      }
55  
56      if (best.a <= 0.0) {
57          fs_color = vec4(0.0);
58      } else {
59          fs_color = best;
60      }
61  }
62  
63  
