args.old_str:
#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform sampler2D u_seed;
uniform sampler2D u_prev;
uniform vec2 u_resolution;
uniform int u_pass_iteration;

const float HUGE_DIST = 1e6;

vec4 readInput(vec2 uv) {
    if (u_pass_iteration == 0) {
        return texture(u_seed, uv);
    }
    return texture(u_prev, uv);
}

void main() {
    vec2 clampedUV = clamp(vs_uv, vec2(0.0), vec2(1.0));
    vec4 best = readInput(clampedUV);

    float maxRes = max(u_resolution.x, u_resolution.y);
    maxRes = max(maxRes, 1.0);
    float log2Max = ceil(log2(maxRes));
    float offsetPower = log2Max - 1.0 - float(u_pass_iteration);
    offsetPower = max(offsetPower, 0.0);
    float pixelOffset = exp2(offsetPower);
    vec2 texelOffset = vec2(pixelOffset / u_resolution.x, pixelOffset / u_resolution.y);

    float bestDist2 = HUGE_DIST;
    if (best.a > 0.0) {
        vec2 delta = best.xy - clampedUV;
        bestDist2 = dot(delta, delta);
    }

    for (int y = -1; y <= 1; ++y) {
        for (int x = -1; x <= 1; ++x) {
            vec2 sampleOffset = vec2(float(x), float(y)) * texelOffset;
            vec2 sampleUV = clamp(clampedUV + sampleOffset, vec2(0.0), vec2(1.0));
            vec4 candidate = readInput(sampleUV);
            if (candidate.a <= 0.0) {
                continue;
            }

            vec2 delta = candidate.xy - clampedUV;
            float dist2 = dot(delta, delta);
            if (dist2 < bestDist2) {
                bestDist2 = dist2;
                best = candidate;
            }
        }
    }

    if (best.a <= 0.0) {
        fs_color = vec4(0.0);
    } else {
        fs_color = best;
    }
}

args.new_str:
#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform sampler2D u_seed;
uniform sampler2D u_prev;
uniform vec2 u_resolution;
uniform float u_pass_iteration;

const float HUGE_DIST = 1e6;

vec4 readSource(vec2 uv, bool useSeed) {
    return useSeed ? texture(u_seed, uv) : texture(u_prev, uv);
}

void main() {
    vec2 uv = clamp(vs_uv, vec2(0.0), vec2(1.0));
    float iteration = floor(u_pass_iteration + 0.5);
    bool seedRun = iteration < 0.5;

    vec4 best = readSource(uv, seedRun);
    float bestDist2 = HUGE_DIST;
    if (best.a > 0.0) {
        vec2 delta = best.xy - uv;
        bestDist2 = dot(delta, delta);
    }

    float maxRes = max(max(u_resolution.x, u_resolution.y), 1.0);
    float log2Max = ceil(log2(maxRes));
    float offsetPower = max(log2Max - 1.0 - iteration, 0.0);
    float pixelOffset = exp2(offsetPower);

    vec2 pixelCoord = uv * u_resolution;

    for (int y = -1; y <= 1; ++y) {
        for (int x = -1; x <= 1; ++x) {
            vec2 neighbour = pixelCoord + vec2(float(x), float(y)) * pixelOffset;
            if (any(lessThan(neighbour, vec2(0.0))) || any(greaterThanEqual(neighbour, u_resolution))) {
                continue;
            }

            vec2 sampleUV = neighbour / u_resolution;
            vec4 candidate = readSource(sampleUV, seedRun);
            if (candidate.a <= 0.0) {
                continue;
            }

            vec2 delta = candidate.xy - uv;
            float dist2 = dot(delta, delta);
            if (dist2 < bestDist2) {
                bestDist2 = dist2;
                best = candidate;
            }
        }
    }

    fs_color = (best.a > 0.0) ? best : vec4(0.0);
}

