#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform vec2 u_resolution;
uniform sampler2D u_seed;
uniform sampler2D u_prev;
uniform float u_pass_iteration;

const float HUGE_DIST = 1e6;

vec4 sampleSource(vec2 uv, bool useSeed) {
    return useSeed ? texture(u_seed, uv) : texture(u_prev, uv);
}

void main() {
    vec2 uv = clamp(vs_uv, vec2(0.0), vec2(1.0));
    vec2 resolution = max(u_resolution, vec2(1.0));

    float iterationF = clamp(round(u_pass_iteration), 0.0, 11.0);
    int iteration = int(iterationF);
    bool seedRun = (iteration == 0);

    vec4 best = sampleSource(uv, seedRun);
    float bestDist2 = (best.a > 0.0) ? dot(best.xy - uv, best.xy - uv) : HUGE_DIST;

    float log2Max = ceil(log2(max(resolution.x, resolution.y)));
    float offsetPower = max(log2Max - 1.0 - iterationF, 0.0);
    float pixelStep = exp2(offsetPower);

    vec2 pixelBounds = max(resolution - vec2(1.0), vec2(0.0));
    vec2 pixelCoord = clamp(uv * resolution, vec2(0.0), pixelBounds);

    for (int y = -1; y <= 1; ++y) {
        for (int x = -1; x <= 1; ++x) {
            vec2 neighbour = pixelCoord + vec2(float(x), float(y)) * pixelStep;
            neighbour = clamp(neighbour, vec2(0.0), pixelBounds);
            vec2 sampleUV = neighbour / resolution;

            vec4 candidate = sampleSource(sampleUV, seedRun);
            if (candidate.a <= 0.0) {
                continue;
            }

            float dist2 = dot(candidate.xy - uv, candidate.xy - uv);
            if (dist2 < bestDist2) {
                bestDist2 = dist2;
                best = candidate;
            }
        }
    }

    fs_color = (best.a > 0.0) ? best : vec4(0.0);
}

args.new_text:
#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform vec2 u_resolution;
uniform sampler2D u_seed;
uniform sampler2D u_prev;
uniform float u_pass_iteration;

const float HUGE_DIST = 1e6;

vec4 sampleField(vec2 uv, bool useSeed) {
    return useSeed ? texture(u_seed, uv) : texture(u_prev, uv);
}

vec2 uvFromPixel(ivec2 pixel, vec2 resolution) {
    return (vec2(pixel) + 0.5) / resolution;
}

int ceilLog2(int value) {
    int result = 0;
    int power = 1;
    while (power < value) {
        power <<= 1;
        ++result;
    }
    return result;
}

void main() {
    vec2 resolution = max(u_resolution, vec2(1.0));
    ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
    ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);

    int iteration = clamp(int(round(u_pass_iteration)), 0, 11);
    bool useSeed = (iteration == 0);

    vec2 centerUV = uvFromPixel(coord, resolution);
    vec4 best = sampleField(centerUV, useSeed);
    float bestDist2 = (best.a > 0.0) ? dot(best.xy - centerUV, best.xy - centerUV) : HUGE_DIST;

    int maxRes = max(res.x, res.y);
    maxRes = max(maxRes, 1);
    int log2Max = ceilLog2(maxRes);
    int stepExp = max(log2Max - 1 - iteration, 0);
    int pixelStep = 1 << stepExp;

    for (int y = -1; y <= 1; ++y) {
        for (int x = -1; x <= 1; ++x) {
            ivec2 neighbour = clamp(coord + ivec2(x, y) * pixelStep, ivec2(0), res - 1);
            vec2 sampleUV = uvFromPixel(neighbour, resolution);
            vec4 candidate = sampleField(sampleUV, useSeed);
            if (candidate.a <= 0.0) {
                continue;
            }

            float dist2 = dot(candidate.xy - centerUV, candidate.xy - centerUV);
            if (dist2 < bestDist2) {
                bestDist2 = dist2;
                best = candidate;
            }
        }
    }

    fs_color = (best.a > 0.0) ? best : vec4(0.0);
}

