 7  
 8  void main() {
 9      vec4 source = texture(u_jfa, vs_uv);
10      float dist = source.a > 0.0 ? length(source.xy - vs_uv) : 1.0;
11      fs_color = vec4(dist, 0.0, 0.0, 1.0);
12  }
