=== PASS jfa (edit as: c5c9#jfa) [output] ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform vec2 u_resolution;
 7  uniform sampler2D u_seed;
 8  uniform sampler2D u_prev;
 9  uniform float u_pass_iteration;
10  
11  const float HUGE_DIST = 1e6;
12  
13  vec4 sampleField(vec2 uv, bool useSeed) {
14      return useSeed ? texture(u_seed, uv) : texture(u_prev, uv);
15  }
16  
17  vec2 uvFromPixel(ivec2 pixel, vec2 resolution) {
18      return (vec2(pixel) + 0.5) / resolution;
19  }
20  
21  int ceilLog2(int value) {
22      int result = 0;
23      int power = 1;
24      while (power < value) {
25          power <<= 1;
26          ++result;
27      }
28      return result;
29  }
30  
31  void main() {
32      vec2 resolution = max(u_resolution, vec2(1.0));
33      ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
34      ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);
35  
36      int iteration = clamp(int(round(u_pass_iteration)), 0, 11);
37      bool useSeed = (iteration == 0);
38  
39      vec2 centerUV = uvFromPixel(coord, resolution);
40      vec4 best = sampleField(centerUV, useSeed);
41      float bestDist2 = (best.a > 0.0) ? dot(best.xy - centerUV, best.xy - centerUV) : HUGE_DIST;
42  
43      int maxRes = max(res.x, res.y);
44      maxRes = max(maxRes, 1);
45      int log2Max = ceilLog2(maxRes);
46      int stepExp = max(log2Max - 1 - iteration, 0);
47      int pixelStep = 1 << stepExp;
48  
49      for (int y = -1; y <= 1; ++y) {
50          for (int x = -1; x <= 1; ++x) {
51              ivec2 neighbour = clamp(coord + ivec2(x, y) * pixelStep, ivec2(0), res - 1);
52              vec2 sampleUV = uvFromPixel(neighbour, resolution);
53              vec4 candidate = sampleField(sampleUV, useSeed);
54              if (candidate.a <= 0.0) {
55                  continue;
56              }
57  
58              float dist2 = dot(candidate.xy - centerUV, candidate.xy - centerUV);
59              if (dist2 < bestDist2) {
60                  bestDist2 = dist2;
61                  best = candidate;
62              }
63          }
64      }
65  
66      fs_color = (best.a > 0.0) ? best : vec4(0.0);
67  }
68  
uniforms:
u_pass_iteration float = 11.0
u_prev sampler2D <- jfa
u_resolution vec2 = (64, 48)
u_seed sampler2D <- seed
errors:
none
=== PASS paint (edit as: c5c9#paint) ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform float u_aspect;
 7  
 8  void main() {
 9      vec2 centered = vs_uv * 2.0 - 1.0;
10      centered.x *= u_aspect;
11  
12      const vec2 warmCenter = vec2(-0.33, -0.05);
13      const vec2 coolCenter = vec2(0.35, 0.08);
14      const float radius = 0.33;
15      const float edge = 0.012;
16      const float wallWidth = 0.01;
17  
18      float warmDist = length(centered - warmCenter);
19      float coolDist = length(centered - coolCenter);
20  
21      float warmMask = 1.0 - smoothstep(radius - edge, radius + edge, warmDist);
22      float coolMask = 1.0 - smoothstep(radius - edge, radius + edge, coolDist);
23      float wallSoft = smoothstep(wallWidth, wallWidth + 0.003, abs(centered.x));
24      float wallMask = 1.0 - wallSoft;
25  
26      vec3 warmColor = vec3(1.0, 0.55, 0.2) * 1.04;
27      vec3 coolColor = vec3(0.15, 0.65, 1.0) * 1.1;
28      vec3 wallColor = vec3(0.02);
29  
30      vec3 discColor = warmColor * warmMask + coolColor * coolMask;
31      vec3 resultColor = mix(discColor, wallColor, wallMask);
32  
33      float vignette = 1.0 - smoothstep(1.0, 1.2, length(centered));
34      resultColor *= vignette;
35  
36      fs_color = vec4(resultColor, 1.0);
37  }
38  
