","new_str":"#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform sampler2D u_jfa;

const float MIN_DIST = 1e-4;

void main() {
    vec4 source = texture(u_jfa, vs_uv);
    float dist = 1.0;
    if (source.a > 0.0) {
        dist = length(source.xy - vs_uv);
        if (dist < MIN_DIST) {
            dist = 0.0;
        }
    }
    fs_color = vec4(dist, 0.0, 0.0, 1.0);
