31  void main() {
32      vec2 resolution = max(u_resolution, vec2(1.0));
33      ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
34      ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);
35  
36      int iteration = clamp(int(round(u_pass_iteration)), 0, 11);
37      bool useSeed = (iteration == 0);
38  
39      vec2 centerUV = uvFromPixel(coord, resolution);
40      vec4 best = sampleField(centerUV, useSeed);
41      float bestDist2 = (best.a > 0.0) ? dot(best.xy - centerUV, best.xy - centerUV) : HUGE_DIST;
42  
43      int maxRes = max(res.x, res.y);
44      maxRes = max(maxRes, 1);
45      int log2Max = ceilLog2(maxRes);
46      int stepExp = max(log2Max - 1 - iteration, 0);
47      int pixelStep = 1 << stepExp;
48  
49      for (int y = -1; y <= 1; ++y) {
50          for (int x = -1; x <= 1; ++x) {
51              ivec2 neighbour = clamp(coord + ivec2(x, y) * pixelStep, ivec2(0), res - 1);
52              vec2 sampleUV = uvFromPixel(neighbour, resolution);
53              vec4 candidate = sampleField(sampleUV, useSeed);
54              if (candidate.a <= 0.0) {
55                  continue;
56              }
57  
58              float dist2 = dot(candidate.xy - centerUV, candidate.xy - centerUV);
59              if (dist2 < bestDist2) {
