void main() {
    vec4 source = texture(u_jfa, vs_uv);
    float dist = 1.0;
    if (source.a > 0.0) {
        dist = length(source.xy - vs_uv);
        if (dist < MIN_DIST) {
            dist = 0.0;
        }
    }
    fs_color = vec4(dist, 0.0, 0.0, 1.0);
}

