in vec2 vs_uv;
out vec4 fs_color;

uniform vec2 u_resolution;
uniform sampler2D u_df;
uniform sampler2D u_paint;
uniform sampler2D u_prev;
uniform float u_pass_iteration;

const int TOTAL_RUNS = 6;
const float BASE = 0.012;
const float HIT_THRESHOLD = 0.0012;
const float MIN_STEP = 0.0006;
const float TWO_PI = 6.28318530718;
const int MAX_STEPS = 128;

vec2 uvFromPixel(ivec2 pixel, vec2 resolution) {
    return (vec2(pixel) + 0.5) / resolution;
}

vec3 sampleUpperProbe(ivec2 upperProbeIndex, ivec2 slotCoord, ivec2 res, vec2 resolution, int sp) {
    int spUp = sp << 1;
    ivec2 blockOrigin = upperProbeIndex * spUp;
    vec3 sum = vec3(0.0);
    for (int oy = 0; oy < 2; ++oy) {
        for (int ox = 0; ox < 2; ++ox) {
            ivec2 slotUp = slotCoord * 2 + ivec2(ox, oy);
            slotUp = clamp(slotUp, ivec2(0), ivec2(spUp - 1));
            ivec2 texel = clamp(blockOrigin + slotUp, ivec2(0), res - 1);
            sum += texture(u_prev, uvFromPixel(texel, resolution)).rgb;
        }
    }
    return sum * 0.25;
}

vec3 mergeFromPrev(int level, ivec2 probeIndex, ivec2 slotCoord, ivec2 res, vec2 resolution, int sp) {
    if (level >= TOTAL_RUNS - 1) {
        return vec3(0.0);
    }

    int spUp = sp << 1;
    ivec2 blockSize = ivec2(spUp);
    ivec2 coarseCount = max((res + blockSize - ivec2(1)) / blockSize, ivec2(1));
    vec2 upperMax = vec2(max(coarseCount - ivec2(1), ivec2(0)));
    vec2 upperFloat = clamp(vec2(probeIndex) / 2.0, vec2(0.0), upperMax);
    ivec2 upperBase = clamp(ivec2(floor(upperFloat)), ivec2(0), coarseCount - ivec2(1));
    vec2 frac = upperFloat - vec2(upperBase);
    vec2 fracClamped = clamp(frac, vec2(0.0), vec2(1.0));
    ivec2 upperMaxIndex = max(coarseCount - ivec2(1), ivec2(0));

    ivec2 upper00 = upperBase;
    ivec2 upper10 = clamp(upperBase + ivec2(1, 0), ivec2(0), upperMaxIndex);
    ivec2 upper01 = clamp(upperBase + ivec2(0, 1), ivec2(0), upperMaxIndex);
    ivec2 upper11 = clamp(upperBase + ivec2(1, 1), ivec2(0), upperMaxIndex);

    vec3 radiance00 = sampleUpperProbe(upper00, slotCoord, res, resolution, sp);
    vec3 radiance10 = sampleUpperProbe(upper10, slotCoord, res, resolution, sp);
    vec3 radiance01 = sampleUpperProbe(upper01, slotCoord, res, resolution, sp);
    vec3 radiance11 = sampleUpperProbe(upper11, slotCoord, res, resolution, sp);

    vec3 blendX0 = mix(radiance00, radiance10, fracClamped.x);
    vec3 blendX1 = mix(radiance01, radiance11, fracClamped.x);
    return mix(blendX0, blendX1, fracClamped.y);
}

void main() {
    vec2 resolution = max(u_resolution, vec2(1.0));
    ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
    ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);

    int iteration = clamp(int(round(u_pass_iteration)), 0, TOTAL_RUNS - 1);
    int level = TOTAL_RUNS - 1 - iteration;
    int sp = 1 << level;

    ivec2 probeIndex = coord / sp;
    ivec2 blockOrigin = probeIndex * sp;
    ivec2 slotCoord = coord - blockOrigin;
    int slot = slotCoord.y * sp + slotCoord.x;
    float totalSlots = float(sp * sp);
    float angle = (float(slot) + 0.5) / totalSlots * TWO_PI;

    vec2 probeUV = (vec2(probeIndex) + 0.5) * float(sp) / vec2(res);
    vec2 dir = vec2(cos(angle), sin(angle));

    float shellMin = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
    float shellMax = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
    float t = max(shellMin, 1e-4);

    vec3 radiance = vec3(0.0);
    bool hit = false;
    for (int i = 0; i < MAX_STEPS && t <= shellMax; ++i) {
        vec2 sampleUV = probeUV + dir * t;
        if (any(lessThan(sampleUV, vec2(0.0))) || any(greaterThan(sampleUV, vec2(1.0)))) {
            break;
        }

        float dist = texture(u_df, sampleUV).r;
        if (dist < HIT_THRESHOLD) {
            radiance = texture(u_paint, sampleUV).rgb;
            hit = true;
            break;
        }

        float step = max(dist, MIN_STEP);
        t += step;
    }

    if (!hit) {
        radiance = mergeFromPrev(level, probeIndex, slotCoord, res, resolution, sp);
    }

    fs_color = vec4(radiance, 1.0);
}
","target":"c5c9#cascade"}

