 80      int slot = slotCoord.y * sp + slotCoord.x;
 81      float totalSlots = float(sp * sp);
 82      float angle = (float(slot) + 0.5) / totalSlots * TWO_PI;
 83  
 84      vec2 probeUV = (vec2(probeIndex) + 0.5) * float(sp) / vec2(res);
 85      vec2 dir = vec2(cos(angle), sin(angle));
 86  
 87      float shellMin = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
 88      float shellMax = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
