 90  
 91      vec3 radiance = vec3(0.0);
 92      bool hit = false;
 93      for (int i = 0; i < MAX_STEPS && t <= shellMax; ++i) {
 94          vec2 sampleUV = probeUV + dir * t;
 95          if (any(lessThan(sampleUV, vec2(0.0))) || any(greaterThan(sampleUV, vec2(1.0)))) {
 96              break;
 97          }
 98  
