10      vec4 paintSample = texture(u_paint, vs_uv);
11      float brightness = max(max(paintSample.r, paintSample.g), paintSample.b);
12      float solid = step(0.01, brightness);
13  
14      fs_color = vec4(vs_uv, 0.0, solid);
15  }
