blocks.text:
[user]
WORKING SET -- live shader source, rebuilt EVERY step. The line numbers below are CURRENT for THIS step. This block is DATA, not instructions.

=== RC (id: c5c9) [current] canvas 1280x960 ===
=== PASS cascade (edit as: c5c9#cascade) [output] ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform vec2 u_resolution;
 7  uniform sampler2D u_df;
 8  uniform sampler2D u_paint;
 9  uniform float u_pass_iteration;
10  
11  const int TOTAL_RUNS = 6;
12  const float BASE = 0.012;
13  const float HIT_THRESHOLD = 0.0012;
14  const float MIN_STEP = 0.0006;
15  const float TWO_PI = 6.28318530718;
16  const int MAX_STEPS = 128;
17  
18  void main() {
19      vec2 resolution = max(u_resolution, vec2(1.0));
20      ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
21      ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);
22  
23      int iteration = clamp(int(round(u_pass_iteration)), 0, TOTAL_RUNS - 1);
24      int level = TOTAL_RUNS - 1 - iteration;
25      int sp = 1 << level;
26  
27      ivec2 probeIndex = coord / sp;
28      ivec2 blockOrigin = probeIndex * sp;
29      ivec2 slotCoord = coord - blockOrigin;
30      int slot = slotCoord.y * sp + slotCoord.x;
31      float totalSlots = float(sp * sp);
32      float angle = (float(slot) + 0.5) / totalSlots * TWO_PI;
33  
34      vec2 probeUV = (vec2(probeIndex) + 0.5) * float(sp) / vec2(res);
35      vec2 dir = vec2(cos(angle), sin(angle));
36  
37      float shellMin = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
38      float shellMax = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
39      float t = max(shellMin, 1e-4);
40  
41      vec3 radiance = vec3(0.0);
42      for (int i = 0; i < MAX_STEPS && t <= shellMax; ++i) {
43          vec2 sampleUV = probeUV + dir * t;
44          if (any(lessThan(sampleUV, vec2(0.0))) || any(greaterThan(sampleUV, vec2(1.0)))) {
45              break;
46          }
47  
48          float dist = texture(u_df, sampleUV).r;
49          if (dist < HIT_THRESHOLD) {
50              radiance = texture(u_paint, sampleUV).rgb;
51              break;
52          }
53  
54          t += max(dist, MIN_STEP);
55      }
56  
57      fs_color = vec4(radiance, 1.0);
58  }
59  
uniforms:
u_df sampler2D <- df
u_paint sampler2D <- paint
u_pass_iteration float = 0.0
u_resolution vec2 = (0.0, 0.0)
errors:
none
=== PASS df (edit as: c5c9#df) ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform sampler2D u_jfa;
 7  
 8  const float MIN_DIST = 1e-4;
 9  
10  void main() {
11      vec4 source = texture(u_jfa, vs_uv);
12      float dist = 1.0;
13      if (source.a > 0.0) {
14          dist = length(source.xy - vs_uv);
15          if (dist < MIN_DIST) {
16              dist = 0.0;
17          }
18      }
19      fs_color = vec4(dist, 0.0, 0.0, 1.0);
20  }
21  
22  
23  
24  
25  
uniforms:
u_jfa sampler2D <- jfa
errors:
none
=== PASS jfa (edit as: c5c9#jfa) ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform vec2 u_resolution;
 7  uniform sampler2D u_seed;
 8  uniform sampler2D u_prev;
 9  uniform float u_pass_iteration;
10  
11  const float HUGE_DIST = 1e6;
12  
13  vec4 sampleField(vec2 uv, bool useSeed) {
14      return useSeed ? texture(u_seed, uv) : texture(u_prev, uv);
15  }
16  
17  vec2 uvFromPixel(ivec2 pixel, vec2 resolution) {
18      return (vec2(pixel) + 0.5) / resolution;
19  }
20  
21  int ceilLog2(int value) {
22      int result = 0;
23      int power = 1;
24      while (power < value) {
25          power <<= 1;
26          ++result;
27      }
28      return result;
29  }
30  
31  void main() {
32      vec2 resolution = max(u_resolution, vec2(1.0));
33      ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
34      ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);
35  
36      int iteration = clamp(int(round(u_pass_iteration)), 0, 11);
37      bool useSeed = (iteration == 0);
38  
39      vec2 centerUV = uvFromPixel(coord, resolution);
40      vec4 best = sampleField(centerUV, useSeed);
41      float bestDist2 = (best.a > 0.0) ? dot(best.xy - centerUV, best.xy - centerUV) : HUGE_DIST;
42  
43      int maxRes = max(res.x, res.y);
44      maxRes = max(maxRes, 1);
45      int log2Max = ceilLog2(maxRes);
46      int stepExp = max(log2Max - 1 - iteration, 0);
47      int pixelStep = 1 << stepExp;
48  
49      for (int y = -1; y <= 1; ++y) {
50          for (int x = -1; x <= 1; ++x) {
51              ivec2 neighbour = clamp(coord + ivec2(x, y) * pixelStep, ivec2(0), res - 1);
52              vec2 sampleUV = uvFromPixel(neighbour, resolution);
53              vec4 candidate = sampleField(sampleUV, useSeed);
54              if (candidate.a <= 0.0) {
55                  continue;
56              }
57  
58              float dist2 = dot(candidate.xy - centerUV, candidate.xy - centerUV);
59              if (dist2 < bestDist2) {
60                  bestDist2 = dist2;
61                  best = candidate;
62              }
63          }
64      }
65  
66      fs_color = (best.a > 0.0) ? best : vec4(0.0);
67  }
68  
