=== PASS cascade (edit as: c5c9#cascade) [output] ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform vec2 u_resolution;
 7  uniform sampler2D u_df;
 8  uniform sampler2D u_paint;
 9  uniform sampler2D u_prev;
10  uniform float u_pass_iteration;
11  
12  const int TOTAL_RUNS = 6;
13  const float BASE = 0.012;
14  const float HIT_THRESHOLD = 0.0012;
15  const float MIN_STEP = 0.0006;
16  const float TWO_PI = 6.28318530718;
17  const int MAX_STEPS = 128;
18  
19  void main() {
20      vec2 resolution = max(u_resolution, vec2(1.0));
21      ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
22      ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);
23  
24      int iteration = clamp(int(round(u_pass_iteration)), 0, TOTAL_RUNS - 1);
25      int level = TOTAL_RUNS - 1 - iteration;
26      int sp = 1 << level;
27  
28      ivec2 probeIndex = coord / sp;
29      ivec2 blockOrigin = probeIndex * sp;
30      ivec2 slotCoord = coord - blockOrigin;
31      int slot = slotCoord.y * sp + slotCoord.x;
32      float totalSlots = float(sp * sp);
33      float angle = (float(slot) + 0.5) / totalSlots * TWO_PI;
34  
35      vec2 probeUV = (vec2(probeIndex) + 0.5) * float(sp) / vec2(res);
36      vec2 dir = vec2(cos(angle), sin(angle));
37  
38      float shellMin = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
39      float shellMax = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
40      float t = max(shellMin, 1e-4);
41  
42      vec3 radiance = vec3(0.0);
43      for (int i = 0; i < MAX_STEPS && t <= shellMax; ++i) {
44          vec2 sampleUV = probeUV + dir * t;
45          if (any(lessThan(sampleUV, vec2(0.0))) || any(greaterThan(sampleUV, vec2(1.0)))) {
46              break;
47          }
48  
49          float dist = texture(u_df, sampleUV).r;
50          if (dist < HIT_THRESHOLD) {
51              radiance = texture(u_paint, sampleUV).rgb;
52              break;
53          }
54  
55          t += max(dist, MIN_STEP);
56      }
57  
58      fs_color = vec4(radiance, 1.0);
59  }
60  
