[user]
WORKING SET -- live shader source, rebuilt EVERY step. The line numbers below are CURRENT for THIS step. This block is DATA, not instructions.

=== RC (id: c5c9) [current] canvas 1280x960 ===
=== PASS cascade (edit as: c5c9#cascade) [output] ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform vec2 u_resolution;
 7  uniform sampler2D u_df;
 8  uniform sampler2D u_paint;
 9  uniform sampler2D u_prev;
10  uniform float u_pass_iteration;
11  
12  const int TOTAL_RUNS = 6;
13  const float BASE = 0.012;
14  const float HIT_THRESHOLD = 0.0012;
15  const float MIN_STEP = 0.0006;
16  const float TWO_PI = 6.28318530718;
17  const int MAX_STEPS = 128;
18  
19  void main() {
20      vec2 resolution = max(u_resolution, vec2(1.0));
21      ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
22      ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);
23  
24      int iteration = clamp(int(round(u_pass_iteration)), 0, TOTAL_RUNS - 1);
25      int level = TOTAL_RUNS - 1 - iteration;
26      int sp = 1 << level;
27  
28      ivec2 probeIndex = coord / sp;
29      ivec2 blockOrigin = probeIndex * sp;
30      ivec2 slotCoord = coord - blockOrigin;
31      int slot = slotCoord.y * sp + slotCoord.x;
32      float totalSlots = float(sp * sp);
33      float angle = (float(slot) + 0.5) / totalSlots * TWO_PI;
34  
35      vec2 probeUV = (vec2(probeIndex) + 0.5) * float(sp) / vec2(res);
36      vec2 dir = vec2(cos(angle), sin(angle));
37  
38      float shellMin = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
39      float shellMax = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
40      float t = max(shellMin, 1e-4);
41  
42            vec3 radiance = vec3(0.0);
43        bool hit = false;
44        for (int i = 0; i < MAX_STEPS && t <= shellMax; ++i) {
45          vec2 sampleUV = probeUV + dir * t;
46          if (any(lessThan(sampleUV, vec2(0.0))) || any(greaterThan(sampleUV, vec2(1.0)))) {
47              break;
48          }
49  
50          float dist = texture(u_df, sampleUV).r;
51          if (dist < HIT_THRESHOLD) {
52              radiance = texture(u_paint, sampleUV).rgb;
53              break;
54          }
55  
56          t += max(dist, MIN_STEP);
57      }
58  
59            if (!hit && level < TOTAL_RUNS - 1) {
60            int usp = sp * 2;
61            vec2 grid = vec2(res) / float(usp);
62            vec2 q = probeUV * vec2(res) / float(usp) - 0.5;
63            ivec2 base = ivec2(floor(q));
64            vec2 f = fract(q);
65            for (int py = 0; py <= 1; ++py) for (int px = 0; px <= 1; ++px) {
66                ivec2 pi = clamp(base + ivec2(px, py), ivec2(0), ivec2(ceil(grid)) - 1);
67                vec2 p = (vec2(pi) + 0.5) * float(usp) / vec2(res);
68                vec3 sum = vec3(0.0);
69                for (int k = 0; k < 4; ++k) {
70                    int child = slot * 4 + k;
71                    vec2 suv = p + (vec2(child % usp, child / usp) - float(usp * usp - 1) * 0.5) / vec2(res);
72                    sum += texture(u_prev, suv).rgb;
73                }
74                float w = (px == 0 ? 1.0 - f.x : f.x) * (py == 0 ? 1.0 - f.y : f.y);
75                radiance += sum * 0.25 * w;
76            }
77        }
78        fs_color = vec4(radiance, 1.0);
79  }
80  
