payload.assistant_text:
Done:

- `seed` target changed from `f1` to `f4`, preserving nearest filtering.
- `cascade` declares `u_prev` and now merges shell misses from the previous run:
  - averages the four child slots `idx * 4 + k`;
  - computes the four neighboring upper probes;
  - performs manual bilinear weighting;
  - clamps probe indices at the canvas edges, with no wrapping.
- `cascade` remains the output pass.
- Both modified passes compile cleanly.

args.new_str:
uniform sampler2D u_paint;
uniform sampler2D u_prev;
uniform float u_pass_iteration;

vec3 radiance = vec3(0.0);
bool hit = false;
for (int i = 0; i < MAX_STEPS && t <= shellMax; ++i) {

if (!hit && level < TOTAL_RUNS - 1) {
    int usp = sp * 2;
    vec2 grid = vec2(res) / float(usp);
    vec2 q = probeUV * vec2(res) / float(usp) - 0.5;
    ivec2 base = ivec2(floor(q));
    vec2 f = fract(q);
    for (int py = 0; py <= 1; ++py) for (int px = 0; px <= 1; ++px) {
        ivec2 pi = clamp(base + ivec2(px, py), ivec2(0), ivec2(ceil(grid)) - 1);
        vec2 p = (vec2(pi) + 0.5) * float(usp) / vec2(res);
        vec3 sum = vec3(0.0);
        for (int k = 0; k < 4; ++k) {
            int child = slot * 4 + k;
            vec2 suv = p + (vec2(child % usp, child / usp) - float(usp * usp - 1) * 0.5) / vec2(res);
            sum += texture(u_prev, suv).rgb;
        }
        float w = (px == 0 ? 1.0 - f.x : f.x) * (py == 0 ? 1.0 - f.y : f.y);
        radiance += sum * 0.25 * w;
    }
}
fs_color = vec4(radiance, 1.0);

