 9  
10  void main() {
11      vec4 source = texture(u_jfa, vs_uv);
12      float dist = 1.0;
13      if (source.a > 0.0) {
14          dist = length(source.xy - vs_uv);
15          if (dist < MIN_DIST) {
16              dist = 0.0;
17          }
18      }
