in vec2 vs_uv;
out vec4 fs_color;

uniform vec2 u_resolution;
uniform sampler2D u_df;
uniform sampler2D u_paint;
uniform sampler2D u_prev;
uniform float u_pass_iteration;

const int TOTAL_RUNS = 6;
const float BASE = 0.012;
const float HIT_THRESHOLD = 0.0012;
const float MIN_STEP = 0.0006;
const float TWO_PI = 6.28318530718;
const int MAX_STEPS = 128;

void main() {
    vec2 resolution = max(u_resolution, vec2(1.0));
    ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
    ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);
    int iteration = clamp(int(round(u_pass_iteration)), 0, TOTAL_RUNS - 1);
    int level = TOTAL_RUNS - 1 - iteration;
    int sp = 1 << level;
    ivec2 probe = coord / sp;
    ivec2 slotXY = coord - probe * sp;
    int slot = slotXY.y * sp + slotXY.x;
    float slots = float(sp * sp);
    float angle = (float(slot) + 0.5) / slots * TWO_PI;
    vec2 p = (vec2(probe) + 0.5) * float(sp) / vec2(res);
    vec2 dir = vec2(cos(angle), sin(angle));
    float lo = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
    float hi = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
    float t = max(lo, 1e-4);
    vec3 radiance = vec3(0.0);
    bool hit = false;
    for (int i = 0; i < MAX_STEPS && t <= hi; ++i) {
        vec2 q = p + dir * t;
        if (any(lessThan(q, vec2(0.0))) || any(greaterThan(q, vec2(1.0)))) break;
        float d = texture(u_df, q).r;
        if (d < HIT_THRESHOLD) {
            radiance = texture(u_paint, q).rgb;
            hit = true;
            break;
        }
        t += max(d, MIN_STEP);
    }
    if (!hit && level < TOTAL_RUNS - 1) {
        int usp = sp * 2;
        vec2 upperGrid = ceil(vec2(res) / float(usp));
        vec2 q = p * vec2(res) / float(usp) - 0.5;
        ivec2 b = ivec2(floor(q));
        vec2 f = fract(q);
        for (int y = 0; y < 2; ++y) for (int x = 0; x < 2; ++x) {
            ivec2 pi = clamp(b + ivec2(x, y), ivec2(0), ivec2(upperGrid) - 1);
            vec2 up = (vec2(pi) + 0.5) * float(usp) / vec2(res);
            vec3 sum = vec3(0.0);
            for (int k = 0; k < 4; ++k) {
                int child = slot * 4 + k;
                vec2 off = vec2(child % usp, child / usp) - float(usp - 1) * 0.5;
                sum += texture(u_prev, up + off / vec2(res)).rgb;
            }
            float w = (x == 0 ? 1.0 - f.x : f.x) * (y == 0 ? 1.0 - f.y : f.y);
            radiance += 0.25 * w * sum;
        }
    }
    fs_color = vec4(radiance, 1.0);
}","target":"c5c9#cascade"}

