 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform sampler2D u_jfa;
 7  
 8  const float MIN_DIST = 1e-4;
 9  
10  void main() {
11      vec4 source = texture(u_jfa, vs_uv);
12      float dist = 1.0;
13      if (source.a > 0.0) {
14          dist = length(source.xy - vs_uv);
15          if (dist < MIN_DIST) {
16              dist = 0.0;
17          }
18      }
19      fs_color = vec4(dist, 0.0, 0.0, 1.0);
20  }
21  
22  
23  
24  
25  
uniforms:
u_jfa sampler2D <- jfa
