=== PASS paint (edit as: c5c9#paint) ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform float u_aspect;
 7  
 8  void main() {
 9      vec2 centered = vs_uv * 2.0 - 1.0;
10      centered.x *= u_aspect;
11  
12      const vec2 warmCenter = vec2(-0.33, -0.05);
13      const vec2 coolCenter = vec2(0.35, 0.08);
14      const float radius = 0.33;
15      const float edge = 0.012;
16      const float wallWidth = 0.01;
17  
18      float warmDist = length(centered - warmCenter);
19      float coolDist = length(centered - coolCenter);
20  
21      float warmMask = 1.0 - smoothstep(radius - edge, radius + edge, warmDist);
22      float coolMask = 1.0 - smoothstep(radius - edge, radius + edge, coolDist);
23      float wallSoft = smoothstep(wallWidth, wallWidth + 0.003, abs(centered.x));
24      float wallMask = 1.0 - wallSoft;
25  
26      vec3 warmColor = vec3(1.0, 0.55, 0.2) * 1.04;
27      vec3 coolColor = vec3(0.15, 0.65, 1.0) * 1.1;
28      vec3 wallColor = vec3(0.02);
29  
30      vec3 discColor = warmColor * warmMask + coolColor * coolMask;
31      vec3 resultColor = mix(discColor, wallColor, wallMask);
32  
33      float vignette = 1.0 - smoothstep(1.0, 1.2, length(centered));
34      resultColor *= vignette;
35  
36      fs_color = vec4(resultColor, 1.0);
37  }
38  
