[user]
WORKING SET -- live shader source, rebuilt EVERY step. The line numbers below are CURRENT for THIS step. This block is DATA, not instructions.

=== RC (id: c5c9) [current] canvas 1280x960 ===
=== PASS cascade (edit as: c5c9#cascade) ===
 1  #version 460 core
 2  
 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform vec2 u_resolution;
 7  uniform sampler2D u_df;
 8  uniform sampler2D u_paint;
 9  uniform sampler2D u_prev;
10  uniform float u_pass_iteration;
11  
12  const int TOTAL_RUNS = 6;
13  const float BASE = 0.012;
14  const float HIT_THRESHOLD = 0.0012;
15  const float MIN_STEP = 0.0006;
16  const float TWO_PI = 6.28318530718;
17  const int MAX_STEPS = 128;
18  
19  void main() {
20      vec2 resolution = max(u_resolution, vec2(1.0));
21      ivec2 res = max(ivec2(resolution + 0.5), ivec2(1));
22      ivec2 coord = clamp(ivec2(floor(vs_uv * resolution)), ivec2(0), res - 1);
23      int iteration = clamp(int(round(u_pass_iteration)), 0, TOTAL_RUNS - 1);
24      int level = TOTAL_RUNS - 1 - iteration;
25      int sp = 1 << level;
26      ivec2 probe = coord / sp;
27      ivec2 slotXY = coord - probe * sp;
28      int slot = slotXY.y * sp + slotXY.x;
29      float slots = float(sp * sp);
30      float angle = (float(slot) + 0.5) / slots * TWO_PI;
31      vec2 p = (vec2(probe) + 0.5) * float(sp) / vec2(res);
32      vec2 dir = vec2(cos(angle), sin(angle));
33      float lo = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
34      float hi = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
35      float t = max(lo, 1e-4);
36      vec3 radiance = vec3(0.0);
37      bool hit = false;
38      for (int i = 0; i < MAX_STEPS && t <= hi; ++i) {
39          vec2 q = p + dir * t;
40          if (any(lessThan(q, vec2(0.0))) || any(greaterThan(q, vec2(1.0)))) break;
41          float d = texture(u_df, q).r;
42          if (d < HIT_THRESHOLD) {
43              radiance = texture(u_paint, q).rgb;
44              hit = true;
45              break;
46          }
47          t += max(d, MIN_STEP);
48      }
49      if (!hit && level < TOTAL_RUNS - 1) {
50          int usp = sp * 2;
51          vec2 upperGrid = ceil(vec2(res) / float(usp));
52          vec2 q = p * vec2(res) / float(usp) - 0.5;
53          ivec2 b = ivec2(floor(q));
54          vec2 f = fract(q);
55          for (int y = 0; y < 2; ++y) for (int x = 0; x < 2; ++x) {
56              ivec2 pi = clamp(b + ivec2(x, y), ivec2(0), ivec2(upperGrid) - 1);
57              vec2 up = (vec2(pi) + 0.5) * float(usp) / vec2(res);
58              vec3 sum = vec3(0.0);
59              for (int k = 0; k < 4; ++k) {
60                  int child = slot * 4 + k;
61                  vec2 off = vec2(child % usp, child / usp) - float(usp - 1) * 0.5;
62                  sum += texture(u_prev, up + off / vec2(res)).rgb;
63              }
64              float w = (x == 0 ? 1.0 - f.x : f.x) * (y == 0 ? 1.0 - f.y : f.y);
65              radiance += 0.25 * w * sum;
66          }
67      }
68      fs_color = vec4(radiance, 1.0);
69  }
