35      float lo = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
36      float hi = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
37      float t = max(lo, 1e-4);
38      vec3 radiance = vec3(0.0);
39      bool hit = false;
40      for (int i = 0; i < MAX_STEPS && t <= hi; ++i) {
41          vec2 q = p + dir * t;
42          if (any(lessThan(q, vec2(0.0))) || any(greaterThan(q, vec2(1.0)))) break;
43          float d = texture(u_df, q).r;
44          if (d < HIT_THRESHOLD) {
45              radiance = texture(u_paint, q).rgb;
46              hit = true;
47              break;
48          }
49          t += max(d, MIN_STEP);
50      }
51      if (!hit && level < TOTAL_RUNS - 1) {
