            int usp = sp * 2;
            vec2 grid = ceil(res / float(usp));
            vec2 q = p * res / float(usp) - 0.5;
            ivec2 b = ivec2(floor(q));
            vec2 f = fract(q);
            int ux = idx % usp;
            int uy = idx / usp;
            for (int y = 0; y < 2; ++y) for (int x = 0; x < 2; ++x) {
                ivec2 pi = clamp(b + ivec2(x, y), ivec2(0), ivec2(grid) - 1);
