#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform vec2 u_resolution;
uniform sampler2D u_df;
uniform sampler2D u_paint;
uniform sampler2D u_prev;
uniform float u_pass_iteration;

const int TOTAL_RUNS = 6;
const float BASE = 0.012;
const float HIT_THRESHOLD = 0.0012;
const float MIN_STEP = 0.0006;
const float TWO_PI = 6.28318530718;
const int MAX_STEPS = 128;

void main() {
    vec2 res = max(u_resolution, vec2(1.0));
    ivec2 pix = ivec2(floor(vs_uv * res));
    int it = clamp(int(round(u_pass_iteration)), 0, TOTAL_RUNS - 1);
    int level = TOTAL_RUNS - 1 - it;
    int sp = 1 << level;
    ivec2 probe = pix / sp;
    ivec2 local = pix - probe * sp;
    int slot = local.y * sp + local.x;
    int rays = 4 * sp * sp;
    vec2 p = (vec2(probe) + 0.5) * float(sp) / res;
    float lo = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
    float hi = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
    vec3 radiance = vec3(0.0);

    for (int k = 0; k < 4; ++k) {
        int idx = slot * 4 + k;
        float angle = TWO_PI * (float(idx) + 0.5) / float(rays);
        vec2 dir = vec2(cos(angle), sin(angle));
        float t = max(lo, 1e-4);
        bool hit = false;
        vec3 ray = vec3(0.0);
        for (int s = 0; s < MAX_STEPS && t <= hi; ++s) {
            vec2 q = p + dir * t;
            if (any(lessThan(q, vec2(0.0))) || any(greaterThan(q, vec2(1.0)))) break;
            float d = texture(u_df, q).r;
            if (d < HIT_THRESHOLD) {
                ray = texture(u_paint, q).rgb;
                hit = true;
                break;
            }
            t += max(d, MIN_STEP);
        }
        if (!hit && level < TOTAL_RUNS - 1) {
            int usp = sp * 2;
            vec2 grid = ceil(res / float(usp));
            vec2 q = p * res / float(usp) - 0.5;
            ivec2 b = ivec2(floor(q));
            vec2 f = fract(q);
            int ux = idx % usp;
            int uy = idx / usp;
            for (int y = 0; y < 2; ++y) for (int x = 0; x < 2; ++x) {
                ivec2 pi = clamp(b + ivec2(x, y), ivec2(0), ivec2(grid) - 1);
                vec2 up = (vec2(pi) + 0.5) * float(usp) / res;
                vec2 uv = up + (vec2(ux, uy) - 0.5 * float(usp - 1)) / res;
                float w = (x == 0 ? 1.0 - f.x : f.x) * (y == 0 ? 1.0 - f.y : f.y);
                ray += w * texture(u_prev, uv).rgb;
            }
        }
        radiance += 0.25 * ray;
    }
    fs_color = vec4(radiance, 1.0);
}

