 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  uniform vec2 u_resolution;
 6  uniform sampler2D u_df;
 7  uniform sampler2D u_paint;
 8  uniform sampler2D u_prev;
 9  uniform float u_pass_iteration;
10  const float BASE=0.012, HIT=0.0012, PI2=6.28318530718;
11  void main(){
12   vec2 r=max(u_resolution,vec2(1)); ivec2 px=ivec2(floor(vs_uv*r));
13   int lev=5-clamp(int(round(u_pass_iteration)),0,5), sp=1<<lev;
14   ivec2 pr=px/sp, lc=px-pr*sp; int si=lc.y*sp+lc.x, nr=4*sp*sp;
15   vec2 p=(vec2(pr)+.5)*float(sp)/r; float lo=BASE*(pow(4.,float(lev))-1.)/3.;
16   float hi=BASE*(pow(4.,float(lev+1))-1.)/3.; vec3 outc=vec3(0);
17   for(int k=0;k<4;k++){
18    int idx=si*4+k; float a=PI2*(float(idx)+.5)/float(nr); vec2 d=vec2(cos(a),sin(a));
19    float t=max(lo,1e-4); vec3 ray=vec3(0); bool hit=false;
20    for(int s=0;s<128 && t<=hi;s++){
21     vec2 q=p+d*t; if(any(lessThan(q,vec2(0)))||any(greaterThan(q,vec2(1))))break;
22     float fd=texture(u_df,q).r; if(fd<HIT){ray=texture(u_paint,q).rgb;hit=true;break;} t+=max(fd,.0006);
23    }
24    if(!hit && lev<5){
25     int usp=sp*2; ivec2 ng=ivec2(ceil(r/float(usp))); vec2 g=p*r/float(usp)-.5;
26     ivec2 b=ivec2(floor(g)); vec2 f=fract(g); int ux=idx%usp, uy=idx/usp;
27     for(int y=0;y<2;y++)for(int x=0;x<2;x++){
28      ivec2 qpr=clamp(b+ivec2(x,y),ivec2(0),ng-1);
29      vec2 q=(vec2(qpr)+.5)*float(usp)/r+(vec2(ux,uy)-.5*float(usp-1))/r;
30      float w=(x==0?1.-f.x:f.x)*(y==0?1.-f.y:f.y); ray+=w*texture(u_prev,q).rgb;
31     }
32    }
33    outc+=ray*.25;
34   }
35   fs_color=vec4(outc,1);
36  }
