const float BASE = 0.012;
const float HIT = 0.0012;
const float PI2 = 6.28318530718;

vec3 sampleUpper(vec2 probeUv, int slot, int spacing, vec2 resolution) {
    int upperSpacing = spacing * 2;
    ivec2 upperGrid = ivec2(ceil(resolution / float(upperSpacing)));
    vec2 gridPosition = probeUv * resolution / float(upperSpacing) - 0.5;
    ivec2 baseProbe = ivec2(floor(gridPosition));
    vec2 fraction = fract(gridPosition);
    int slotX = slot % upperSpacing;
    int slotY = slot / upperSpacing;
    vec3 result = vec3(0.0);

    for (int y = 0; y < 2; y++) {
        for (int x = 0; x < 2; x++) {
            ivec2 probe = clamp(baseProbe + ivec2(x, y), ivec2(0), upperGrid - 1);
            vec2 probeCenter = (vec2(probe) + 0.5) * float(upperSpacing) / resolution;
            vec2 sampleUv = probeCenter + (vec2(slotX, slotY) - 0.5 * float(upperSpacing - 1)) / resolution;
            float weightX = (x == 0) ? 1.0 - fraction.x : fraction.x;
            float weightY = (y == 0) ? 1.0 - fraction.y : fraction.y;
            result += texture(u_prev, sampleUv).rgb * weightX * weightY;
        }
    }
    return result;
}

void main() {
    vec2 resolution = max(u_resolution, vec2(1.0));
    ivec2 pixel = ivec2(floor(vs_uv * resolution));
    int level = 5 - clamp(int(round(u_pass_iteration)), 0, 5);
    int spacing = 1 << level;
    ivec2 probe = pixel / spacing;
    ivec2 local = pixel - probe * spacing;
    int slot = local.y * spacing + local.x;
    int rayCount = 4 * spacing * spacing;
    vec2 probeUv = (vec2(probe) + 0.5) * float(spacing) / resolution;
    float lower = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
    float upper = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
    vec3 radiance = vec3(0.0);

    for (int rayPart = 0; rayPart < 4; rayPart++) {
        int rayIndex = slot * 4 + rayPart;
        float angle = PI2 * (float(rayIndex) + 0.5) / float(rayCount);
        vec2 direction = vec2(cos(angle), sin(angle));
        float distanceAlongRay = max(lower, 0.0001);
        vec3 rayRadiance = vec3(0.0);
        bool hit = false;

        for (int step = 0; step < 128 && distanceAlongRay <= upper; step++) {
            vec2 sampleUv = probeUv + direction * distanceAlongRay;
            if (any(lessThan(sampleUv, vec2(0.0))) || any(greaterThan(sampleUv, vec2(1.0)))) {
                break;
