            distanceAlongRay += max(distanceField, 0.0006);
        }

        if (!hit && level < 5) {
            rayRadiance = sampleUpper(probeUv, rayIndex, spacing, resolution);
        }
        radiance += rayRadiance;
    }

    fs_color = vec4(radiance * 0.25, 1.0);
