50      vec2 probeUv = (vec2(probe) + 0.5) * float(spacing) / resolution;
51      float shellStart = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
52      float shellEnd = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
53      vec3 radiance = vec3(0.0);
54  
55      for (int subRay = 0; subRay < 4; subRay++) {
56          int rayIndex = slot * 4 + subRay;
57          float angle = PI2 * (float(rayIndex) + 0.5) / float(rays);
58          vec2 direction = vec2(cos(angle), sin(angle));
59          float distanceAlongRay = max(shellStart, 0.0001);
60          vec3 rayRadiance = vec3(0.0);
61          bool hit = false;
62  
63          for (int marchStep = 0; marchStep < 128; marchStep++) {
64              if (distanceAlongRay > shellEnd) {
65                  break;
66              }
67              vec2 sampleUv = probeUv + direction * distanceAlongRay;
68              if (any(lessThan(sampleUv, vec2(0.0))) || any(greaterThan(sampleUv, vec2(1.0)))) {
