in vec2 vs_uv;
out vec4 fs_color;

uniform float u_aspect;

void main() {
    vec2 centered = vs_uv * 2.0 - 1.0;
    centered.x *= u_aspect;

    vec2 warmCenter = vec2(-0.33, -0.05);
    vec2 coolCenter = vec2(0.35, 0.08);
    float radius = 0.33;
    float wallWidth = 0.01;

    bool warmSolid = length(centered - warmCenter) <= radius;
    bool coolSolid = length(centered - coolCenter) <= radius;
    bool wallSolid = abs(centered.x) <= wallWidth;

    vec3 warmColor = vec3(4.0, 3.3, 2.0);
    vec3 coolColor = vec3(0.5, 1.2, 4.0);
    vec3 wallColor = vec3(0.0);

    vec3 color = vec3(0.0);
    float alpha = 0.0;

    if (warmSolid) {
        color = warmColor;
        alpha = 1.0;
    }
    if (coolSolid) {
        color = coolColor;
        alpha = 1.0;
    }
    if (wallSolid) {
        color = wallColor;
        alpha = 1.0;
    }

    fs_color = vec4(color, alpha);
}
","target":"c5c9#paint"}

