 3  in vec2 vs_uv;
 4  out vec4 fs_color;
 5  
 6  uniform vec2 u_resolution;
 7  uniform sampler2D u_df;
 8  uniform sampler2D u_paint;
 9  uniform sampler2D u_prev;
10  uniform float u_pass_iteration;
11  
12  const float BASE = 0.012;
13  const float HIT = 0.0012;
14  const float PI2 = 6.28318530718;
15  
16  vec3 sampleUpper(vec2 probeUv, int rayIndex, int spacing, vec2 resolution) {
17      int upperSpacing = spacing * 2;
18      ivec2 upperGrid = ivec2(ceil(resolution / float(upperSpacing)));
19      vec2 gridPosition = probeUv * resolution / float(upperSpacing) - 0.5;
20      ivec2 baseProbe = ivec2(floor(gridPosition));
21      vec2 fraction = fract(gridPosition);
22      int slotX = rayIndex % upperSpacing;
23      int slotY = rayIndex / upperSpacing;
24      vec3 result = vec3(0.0);
25  
26      for (int y = 0; y < 2; y++) {
27          for (int x = 0; x < 2; x++) {
28              ivec2 probe = clamp(baseProbe + ivec2(x, y), ivec2(0), upperGrid - 1);
29              vec2 center = (vec2(probe) + 0.5) * float(upperSpacing) / resolution;
30              vec2 offset = (vec2(slotX, slotY) - 0.5 * float(upperSpacing - 1)) / resolution;
31              float weightX = x == 0 ? 1.0 - fraction.x : fraction.x;
32              float weightY = y == 0 ? 1.0 - fraction.y : fraction.y;
33              result += texture(u_prev, center + offset).rgb * weightX * weightY;
34          }
35      }
36      return result;
37  }
38  
39  void main() {
40      vec2 resolution = max(u_resolution, vec2(1.0));
41      ivec2 pixel = ivec2(floor(vs_uv * resolution));
42      int iteration = clamp(int(round(u_pass_iteration)), 0, 5);
43      int level = 5 - iteration;
44      int spacing = 1 << level;
45      ivec2 probe = pixel / spacing;
46      ivec2 local = pixel - probe * spacing;
47      int slot = local.y * spacing + local.x;
48      int rayCount = 4 * spacing * spacing;
49      vec2 probeUv = (vec2(probe) + 0.5) * float(spacing) / resolution;
50      float shellStart = BASE * (pow(4.0, float(level)) - 1.0) / 3.0;
51      float shellEnd = BASE * (pow(4.0, float(level + 1)) - 1.0) / 3.0;
52      vec3 radiance = vec3(0.0);
53  
54      for (int subRay = 0; subRay < 4; subRay++) {
55          int rayIndex = slot * 4 + subRay;
56          float angle = PI2 * (float(rayIndex) + 0.5) / float(rayCount);
57          vec2 direction = vec2(cos(angle), sin(angle));
58          float distanceAlongRay = max(shellStart, 0.0001);
59          vec3 rayRadiance = vec3(0.0);
60          bool hit = false;
61  
62          for (int marchStep = 0; marchStep < 128; marchStep++) {
63              if (distanceAlongRay > shellEnd) {
64                  break;
65              }
66              vec2 sampleUv = probeUv + direction * distanceAlongRay;
67              if (any(lessThan(sampleUv, vec2(0.0))) || any(greaterThan(sampleUv, vec2(1.0)))) {
68                  break;
69              }
70              float distanceField = texture(u_df, sampleUv).r;
71              if (distanceField < HIT) {
72                  rayRadiance = texture(u_paint, sampleUv).rgb;
73                  hit = true;
74                  break;
75              }
76              distanceAlongRay += max(distanceField, 0.0006);
77          }
78  
79          if (!hit && level < 5) {
80              rayRadiance = sampleUpper(probeUv, rayIndex, spacing, resolution);
81          }
82          radiance += rayRadiance;
83      }
84  
85      fs_color = vec4(radiance * 0.25, 1.0);
86  }
