 1  from shaderbox.scripting import ScriptBehavior, Vec2
 2  
 3  
 4  class Behavior(ScriptBehavior):
 5      def __init__(self):
 6          self.warm = Vec2(-0.33, -0.05)
 7          self.cool = Vec2(0.35, 0.08)
 8          self.warm_velocity = Vec2(0.22, 0.17)
 9          self.cool_velocity = Vec2(-0.19, 0.21)
10  
11      def update(self, ctx):
12          dt = max(0.0, min(ctx.dt, 0.05))
13          radius = 0.33
14          self.warm = self.warm + self.warm_velocity * dt
15          self.cool = self.cool + self.cool_velocity * dt
16          for name in ("warm", "cool"):
17              position = getattr(self, name)
18              velocity = getattr(self, name + "_velocity")
19              if position.x < -1.333 + radius or position.x > 1.333 - radius:
20                  velocity = Vec2(-velocity.x, velocity.y)
21                  position = Vec2(max(-1.333 + radius, min(1.333 - radius, position.x)), position.y)
22              if position.y < -1.0 + radius or position.y > 1.0 - radius:
23                  velocity = Vec2(velocity.x, -velocity.y)
24                  position = Vec2(position.x, max(-1.0 + radius, min(1.0 - radius, position.y)))
25              setattr(self, name, position)
26              setattr(self, name + "_velocity", velocity)
27          return {"u_warm": self.warm, "u_cool": self.cool}
