 1  from shaderbox.scripting import ScriptBehavior, Vec2
 2  
 3  
 4  class Behavior(ScriptBehavior):
 5      def __init__(self):
 6          self.warm = Vec2(-0.33, -0.05)
 7          self.cool = Vec2(0.35, 0.08)
 8          self.warm_velocity = Vec2(0.22, 0.17)
 9          self.cool_velocity = Vec2(-0.19, 0.21)
10  
11      def update(self, ctx):
12          dt = max(0.0, min(ctx.dt, 0.05))
13          self.warm = self.warm + self.warm_velocity * dt
14          self.cool = self.cool + self.cool_velocity * dt
15          bounds_x = 1.333333 - 0.33
16          bounds_y = 1.0 - 0.33
17  
18          for name in ("warm", "cool"):
19              position = getattr(self, name)
20              velocity = getattr(self, name + "_velocity")
21              if position.x < -bounds_x or position.x > bounds_x:
22                  velocity = Vec2(-velocity.x, velocity.y)
23                  position = Vec2(max(-bounds_x, min(bounds_x, position.x)), position.y)
24              if position.y < -bounds_y or position.y > bounds_y:
25                  velocity = Vec2(velocity.x, -velocity.y)
26                  position = Vec2(position.x, max(-bounds_y, min(bounds_y, position.y)))
27              setattr(self, name, position)
28              setattr(self, name + "_velocity", velocity)
29  
30          return {"paint": {"u_warm": self.warm, "u_cool": self.cool}}
