10  void main() {
11      vec2 p = vs_uv * 2.0 - 1.0;
12      p.x *= u_resolution.x / u_resolution.y;
13      vec2 a = u_line.xy * 2.0 - 1.0;
14      vec2 b = u_line.zw * 2.0 - 1.0;
15      a.x *= u_resolution.x / u_resolution.y;
16      b.x *= u_resolution.x / u_resolution.y;
17      vec2 ab = b - a;
18      float h = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-8), 0.0, 1.0);
19      float distanceToLine = length(p - mix(a, b, h));
20      float stroke = distanceToLine <= 0.006 ? 1.0 : 0.0;
21      float previous = texture(u_prev, vs_uv).a;
22      fs_color = vec4(max(stroke, previous));
23  }
