25                  velocity = Vec2(velocity.x, -velocity.y)
26                  position = Vec2(position.x, max(-bounds_y, min(bounds_y, position.y)))
27              setattr(self, name, position)
28              setattr(self, name + "_velocity", velocity)
29  
30          return {"paint": {"u_warm": self.warm, "u_cool": self.cool}}
