class Behavior(ScriptBehavior):
    def __init__(self):
        self.warm = Vec2(-0.33, -0.05)
        self.cool = Vec2(0.35, 0.08)
        self.warm_velocity = Vec2(0.22, 0.17)
        self.cool_velocity = Vec2(-0.19, 0.21)
        self.line = [-1.0, -1.0, -1.0, -1.0]

    def update(self, ctx):
        dt = max(0.0, min(ctx.dt, 0.05))
        self.warm = self.warm + self.warm_velocity * dt
        self.cool = self.cool + self.cool_velocity * dt
        bounds_x = 1.333333 - 0.33
        bounds_y = 1.0 - 0.33

        for name in ("warm", "cool"):
            position = getattr(self, name)
            velocity = getattr(self, name + "_velocity")
            if position.x < -bounds_x or position.x > bounds_x:
                velocity = Vec2(-velocity.x, velocity.y)
                position = Vec2(max(-bounds_x, min(bounds_x, position.x)), position.y)
            if position.y < -bounds_y or position.y > bounds_y:
                velocity = Vec2(velocity.x, -velocity.y)
                position = Vec2(position.x, max(-bounds_y, min(bounds_y, position.y)))
            setattr(self, name, position)
            setattr(self, name + "_velocity", velocity)

        if ctx.mouse.down:
            self.line = [ctx.mouse.prev_x, ctx.mouse.prev_y, ctx.mouse.x, ctx.mouse.y]
        else:
            self.line = [-1.0, -1.0, -1.0, -1.0]
        return {
            "paint": {"u_warm": self.warm, "u_cool": self.cool},
            "canvas": {"u_line": self.line},
        }
