#version 460 core

in vec2 vs_uv;
out vec4 fs_color;

uniform vec2 u_resolution;
uniform sampler2D u_prev;
uniform vec4 u_line;

void main() {
    vec2 p = vs_uv * 2.0 - 1.0;
    p.x *= u_resolution.x / u_resolution.y;
    vec2 a = u_line.xy * 2.0 - 1.0;
    vec2 b = u_line.zw * 2.0 - 1.0;
    a.x *= u_resolution.x / u_resolution.y;
    b.x *= u_resolution.x / u_resolution.y;
    vec2 ab = b - a;
    float h = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-8), 0.0, 1.0);
    float distanceToLine = length(p - mix(a, b, h));
    float stroke = distanceToLine <= 0.006 ? 1.0 : 0.0;
    float previous = texture(u_prev, vs_uv).a;
    fs_color = vec4(max(stroke, previous));
}

